ame":"Appraisal Clause Representation","url":"https://maineinsuranceappraiser.com/appraisal-work/party-appraiser-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/homeowner-dispute-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/commercial-condo-association-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Claim Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/roof-hail-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Microburst Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/windstorm-microburst-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Nor’easter & Hurricane Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/noreaster-hurricane-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/water-damage-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire, Smoke & Puffback Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/fire-smoke-puffback-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Snow Load Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/ice-dam-snow-load-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree Damage Appraisal","url":"https://maineinsuranceappraiser.com/appraisal-work/fallen-tree-limb-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://maineinsuranceappraiser.com/appraisal-work/carrier-estimate-line-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://maineinsuranceappraiser.com/appraisal-work/umpire-neutral-panel-services/"}}]}},{"@type":"WebSite","@id":"https://maineinsuranceappraiser.com/#website","url":"https://maineinsuranceappraiser.com/","name":"Maine Insurance Appraiser","publisher":{"@id":"https://maineinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#webpage","url":"https://maineinsuranceappraiser.com/plain-english-glossary/","name":"Property Claim Glossary | ACV, Umpire, Ice Dam","description":"Plain-English definitions of property claim terms: actual cash value, replacement cost, depreciation, umpire, ice dam, puffback and many more.","inLanguage":"en-US","isPartOf":{"@id":"https://maineinsuranceappraiser.com/#website"},"about":{"@id":"https://maineinsuranceappraiser.com/#business"},"publisher":{"@id":"https://maineinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#primaryimage","url":"https://maineinsuranceappraiser.com/assets/img/photos/calc-desk.webp","width":1200,"height":800},"mainEntity":{"@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#definedtermset"},"breadcrumb":{"@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#breadcrumb"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://maineinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Glossary","item":"https://maineinsuranceappraiser.com/plain-english-glossary/"}],"@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Plain-English property claim glossary","url":"https://maineinsuranceappraiser.com/plain-english-glossary/","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property after depreciation is subtracted from its replacement cost. Many policies pay this amount first and the rest once repairs are complete.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Additional living expense","description":"Coverage for the extra costs of living elsewhere while your home is unlivable after a covered loss, such as rent, meals and mileage above your normal spending.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision of an appraisal panel stating the amount of loss. Under typical wording it is binding on amount once signed by any two of the three panel members.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party ask for a panel to settle a disagreement over the amount of a covered loss.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Bureau of Insurance","description":"The Maine state agency, within the Department of Professional and Financial Regulation, that regulates insurers and takes consumer complaints about claim handling.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Cedar shingle","description":"A wood roofing or siding material common on older Maine capes and coastal cottages. Repair estimates often turn on matching weathered shingles and the higher labor involved.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Coverage A","description":"The part of a homeowners policy that covers the dwelling itself, including attached structures like a connected garage or ell.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Coverage B","description":"The part of a homeowners policy that covers other structures on the property not attached to the house, such as a detached barn, shed or fence.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Coverage C","description":"The part of a homeowners policy that covers personal property, meaning the contents you own such as furniture, clothing and tools.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Coverage D","description":"The part of a homeowners policy that covers loss of use, usually additional living expense or lost rental income while the home cannot be lived in.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, the property, coverage limits, deductibles and the policy period.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you pay before the policy pays. It is usually a flat dollar amount but can be a percentage for some perils.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, subtracted from replacement cost to arrive at actual cash value.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial stake in the outcome of the claim beyond an agreed fee and no relationship that would bias the result. Most appraisal clauses require it.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Ell","description":"A wing attached to a Maine farmhouse, often part of the connected big house, little house, back house and barn layout. Damage to an ell is usually covered as part of the dwelling.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Freeze exclusion","description":"A policy provision denying coverage for frozen pipe damage unless the owner kept heat on or drained the plumbing and shut off the water. Also called a heat-maintenance condition.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Holdback","description":"The depreciation a carrier withholds from an initial payment until repairs or replacement are completed, under a replacement cost policy.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-sealing waterproof membrane installed under roofing along eaves and valleys to stop water backed up by ice dams. Building codes in cold climates often require it at the eaves.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice that forms at the roof edge when melting snow refreezes, causing water to back up under shingles and into ceilings and walls.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in a repair estimate that describes one task or material, with a quantity, unit and price.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs look uniform, for example when a discontinued siding color cannot be matched.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Mitigation","description":"The steps taken right after a loss to prevent further damage, such as tarping a roof, extracting water or running dehumidifiers. Most policies require reasonable mitigation.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Named storm deductible","description":"A separate deductible that applies when damage comes from a named storm or hurricane, often set as a percentage of the dwelling limit. Also called a percentage deductible.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for the added cost of bringing repaired parts of a building up to current building codes, usually limited to a percentage of the dwelling limit.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Overhead and profit","description":"The general contractor’s charge for coordinating trades and running the job, commonly figured as a percentage added to an estimate when several trades are needed.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed that many policies require within a set time after the carrier asks for it.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Puffback","description":"A misfire in an oil burner that blows soot and smoke through the furnace, ductwork and living space. Cleanup can reach every surface in the house.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that a replacement cost policy pays back once repairs or replacement are completed and documented.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without subtracting depreciation.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed for each, which forms the basis of an estimate.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface. Estimates count roofing in squares, plus a waste allowance.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Standing-seam metal roof","description":"A metal roof with raised interlocking seams, common in Maine snow country because it sheds snow well. Repairs often involve whole panels rather than small patches.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on roofs above a certain pitch, reflecting the extra safety gear and time steep slopes demand.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Storm surge","description":"Coastal flooding pushed ashore by a storm’s winds. It is treated as flood and excluded under standard homeowners policies.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment after the first estimate, usually because hidden damage was found or items were missed.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Surplus lines carrier","description":"An insurer not licensed as a standard admitted carrier in the state but allowed to write coverage that the standard market will not. Many hard-to-place Maine homes are insured this way.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel, chosen by the two appraisers, who decides items they cannot agree on.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Unoccupancy","description":"A condition where a building is furnished but nobody is living in it, such as a seasonal camp in winter. Some policies limit certain coverages after a set period of unoccupancy.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Vacancy clause","description":"A policy provision that limits or removes coverage for some perils when a building has been empty of people and most belongings for a stated period, often 30 or 60 days.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Wind-driven rain","description":"Rain forced into a building by high winds. Policies often cover it only when wind first creates an opening in the roof or walls.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurance carriers and adjusters to price repairs line by line using regional price lists.","inDefinedTermSet":"https://maineinsuranceappraiser.com/plain-english-glossary/"}],"@id":"https://maineinsuranceappraiser.com/plain-english-glossary/#definedtermset"}]}</script>
</head>
